def test_run_check_harness_callable_3():
    import ast
    import inspect
    import json
    import pennylane as qml
    import pennylane.numpy as np
    import builtins as _b

    sol = _b.INJECTED_SOLUTION_CODE

    # Verify AST parsing
    tree = ast.parse(sol)
    assert isinstance(tree, ast.Module), "Parsed AST should be an ast.Module instance"

    ns = {"json": json, "qml": qml, "np": np, "__builtins__": __builtins__}
    exec(sol, ns)

    # Verify run is callable and returns a string
    assert callable(ns["run"]), "'run' must be callable"
    assert callable(ns["check"]), "'check' must be callable"

    # Verify run has exactly 1 parameter
    run_sig = inspect.signature(ns["run"])
    run_params = list(run_sig.parameters.values())
    assert len(run_params) == 1, (
        f"'run' should accept exactly 1 parameter, found {len(run_params)}"
    )

    # Verify check has exactly 2 parameters
    check_sig = inspect.signature(ns["check"])
    check_params = list(check_sig.parameters.values())
